const body = $input.first().json.body || $input.first().json;

const fromEmail = (body.from || body.from_email || '').toLowerCase().trim();
const subject = body.subject || 'No Subject';
const text = body.text || body.body || '';

// Deterministic opt-out keyword check (Safety safeguard before AI)
const optOutPattern = /\b(unsubscribe|remove\s+me|stop\s+emailing|opt\s*out|take\s+me\s+off|please\s+suppress)\b/i;
const isDeterministicOptOut = optOutPattern.test(text) || optOutPattern.test(subject);

// Deterministic bounce check
const isBounce = /mailer-daemon|postmaster|delivery\s+status\s+notification|undeliverable/i.test(fromEmail) || /failed|undelivered|bounce/i.test(subject);

return [{
  json: {
    from_email: fromEmail,
    subject: subject,
    body_text: text,
    provider_message_id: body.provider_message_id || 'reply-' + Date.now(),
    thread_id: body.thread_id || null,
    is_opt_out: isDeterministicOptOut,
    is_bounce: isBounce
  }
}];

