const safe = $('Deterministic Safeguards').first().json;
const lead = $('Lookup Contact & Lead').first().json;
const resp = $input.first().json;
let parsed = {};

try {
  const rawText = resp.candidates[0].content.parts[0].text;
  const cleanJson = rawText.replace(/```json/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleanJson);
} catch (e) {
  parsed = { classification: 'unclear', confidence_score: 0.5, summary: 'Manual review required' };
}

// Deterministic override takes strict precedence over AI
let finalClassification = parsed.classification || 'unclear';
if (safe.is_opt_out) finalClassification = 'unsubscribe';
if (safe.is_bounce) finalClassification = 'bounce';

return [{
  json: {
    contact_id: lead.contact_id || null,
    lead_id: lead.lead_id || null,
    company_name: lead.company_name || 'Prospect',
    from_email: safe.from_email,
    subject: safe.subject,
    body_text: safe.body_text,
    provider_message_id: safe.provider_message_id,
    thread_id: safe.thread_id,
    classification: finalClassification,
    confidence_score: parsed.confidence_score || 0.9,
    summary: parsed.summary || ''
  }
}];

